import React from 'react';
import { CheckCircle2, AlertTriangle, ShieldCheck } from 'lucide-react';

const SkillBadge = ({ skill, type = 'matched', evidence }) => {
  const isMatched = type === 'matched';
  const isVerified = type === 'verified';

  if (isVerified) {
    return (
      <span className="inline-flex items-center space-x-1.5 px-3 py-1.5 rounded-full text-xs font-mono font-semibold bg-gold-300/15 text-gold-300 border border-gold-300/40 shadow-gold-glow transition-transform hover:scale-105">
        <ShieldCheck className="w-3.5 h-3.5 text-gold-300" />
        <span>{skill}</span>
        {evidence && <span className="text-[10px] text-bronze-200/80 font-normal">({evidence})</span>}
      </span>
    );
  }

  return (
    <span
      className={`inline-flex items-center space-x-1.5 px-3 py-1.5 rounded-full text-xs font-mono font-semibold transition-all duration-200 hover:scale-105 ${
        isMatched
          ? 'bg-bronze-100/15 text-bronze-100 border border-bronze-100/40 shadow-amber-glow'
          : 'bg-bronze-800/80 text-bronze-200 border border-bronze-400/40'
      }`}
    >
      {isMatched ? (
        <CheckCircle2 className="w-3.5 h-3.5 text-gold-300" />
      ) : (
        <AlertTriangle className="w-3.5 h-3.5 text-bronze-400" />
      )}
      <span>{skill}</span>
    </span>
  );
};

export default SkillBadge;
